changeSet.sql:
DELETE FROM knowledge.workflow WHERE name = 'kb_extract';
UPDATE knowledge.workflow
SET meta = '{"role":"facade","invokes_dag":"kb_extract"}'::jsonb,
    description = 'Facade ingest run for a knowledge source download. Gates license/robots, invokes extract DAG, stores under UUID leaf, patches wf_exec_log.',
    updated_at = NOW()
WHERE name = 'kb_ingest_facade';
